args:
s=berd-openai-voice o=xyz.buzz.berd-call.openai a=$2
case $a in api-key) ;; endpoint-*[!0-9a-f]*) exit 1 ;; endpoint-*) [ ${#a} = 73 ] || exit 1 ;; *) exit 1 ;; esac
g() { security $1-generic-password -s $2 -a $3 $4 2>/dev/null; }
case $1 in
status)
g find $s $a >/dev/null; c=$?
[ $c = 44 ] && [ $a = api-key ] && { g find $o openai >/dev/null; c=$?; }
if [ $c = 0 ]; then printf saved
elif [ $c != 44 ]; then printf unreadable
elif [ -n "${OPENAI_API_KEY:-}$(printenv OPENAI_$3_API_KEY)" ]; then printf environment
else printf missing
fi ;;
save)
IFS= read -r k || exit 1
case $k in ''|*[!a-zA-Z0-9_.~+/=:-]*) exit 1 ;; esac
[ $a != api-key ] || case $k in sk-*) ;; *) exit 1 ;; esac
printf 'add-generic-password -U -s %s -a %s -w %s\n' $s $a $k | security -i >/dev/null 2>&1
[ "$(g find $s $a -w)" = $k ] ;;
remove)
d() { g delete $1 $2 >/dev/null; c=$?; [ $c = 0 ] || [ $c = 44 ]; }
d $s $a && { [ $a != api-key ] || d $o openai; } ;;
*) exit 1 ;;
esac
